import{_ as t,a,b as i,c as e}from"./chunks/network-diagram-3.CZ3wSHu5.js";import{_ as n,o as d,c as l,a5 as r}from"./chunks/framework.BYXPg_yw.js";const P=JSON.parse('{"title":"네트워크 구성도","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/interface/network.md","filePath":"ko/manual/interface/network.md","lastUpdated":1792139892000}'),o={name:"ko/manual/interface/network.md"};function h(p,s,c,k,F,g){return d(),l("div",null,[...s[0]||(s[0]=[r('<h1 id="네트워크-구성도" tabindex="-1">네트워크 구성도 <a class="header-anchor" href="#네트워크-구성도" aria-label="Permalink to &quot;네트워크 구성도&quot;">​</a></h1><p>네트워크 구성은 로봇에 따라 다릅니다. 두 가지가 달라집니다.</p><ul><li><strong>구성</strong> — <strong>연구용</strong>은 User PC를 로봇 외부에 두고 페이로드를 하나의 LAN 그룹으로 묶습니다. <strong>산업용</strong>은 User PC를 로봇 내부에 탑재하고 페이로드를 각각 개별 연결합니다.</li><li><strong>라우터</strong> — 라우터가 <strong>스위치 허브에 통합된</strong> 로봇은 LTE/5G·Wi-Fi(Mesh) 모듈이 스위치 허브에 직접 연결됩니다. <strong>외장 라우터</strong>를 거치는 로봇도 있습니다.</li></ul><p>모든 구성도에서 <strong>R-PC</strong>는 로봇의 모션 PC, <strong>U-PC</strong>는 사용자 PC입니다. 초록 선은 LAN, 주황 선은 WAN입니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>네트워크 구성은 버전에 따라 다를 수 있습니다. 사용 중인 로봇의 구성이 확실하지 않은 경우 <a href="/RBQ/nightly/ko/manual/support/">문의 부탁드립니다</a>.</p></div></div><h2 id="연구용-구성" tabindex="-1">연구용 구성 <a class="header-anchor" href="#연구용-구성" aria-label="Permalink to &quot;연구용 구성&quot;">​</a></h2><p>U-PC가 로봇 외부에 있습니다. LAN 페이로드(LiDAR, PTZ 카메라, RTK GPS 등)는 스위치 허브에 하나의 연결을 공유합니다.</p><h3 id="라우터가-스위치-허브에-통합된-구성" tabindex="-1">라우터가 스위치 허브에 통합된 구성 <a class="header-anchor" href="#라우터가-스위치-허브에-통합된-구성" aria-label="Permalink to &quot;라우터가 스위치 허브에 통합된 구성&quot;">​</a></h3><figure><img src="'+t+'" alt="네트워크 구성도, 연구용 구성, 라우터가 스위치 허브에 통합"><figcaption style="text-align:center;">[ 연구용 · 라우터 통합 ]</figcaption></figure><h3 id="외장-라우터를-사용하는-구성" tabindex="-1">외장 라우터를 사용하는 구성 <a class="header-anchor" href="#외장-라우터를-사용하는-구성" aria-label="Permalink to &quot;외장 라우터를 사용하는 구성&quot;">​</a></h3><figure><img src="'+a+'" alt="네트워크 구성도, 연구용 구성, 외장 라우터 사용"><figcaption style="text-align:center;">[ 연구용 · 외장 라우터 ]</figcaption></figure><h2 id="산업용-구성" tabindex="-1">산업용 구성 <a class="header-anchor" href="#산업용-구성" aria-label="Permalink to &quot;산업용 구성&quot;">​</a></h2><p>U-PC가 R-PC와 함께 로봇 내부에 탑재되고, 페이로드(LiDAR 1, LiDAR 2, PTZ 카메라)가 각각 스위치 허브에 개별 연결됩니다.</p><h3 id="라우터가-스위치-허브에-통합된-구성-1" tabindex="-1">라우터가 스위치 허브에 통합된 구성 <a class="header-anchor" href="#라우터가-스위치-허브에-통합된-구성-1" aria-label="Permalink to &quot;라우터가 스위치 허브에 통합된 구성&quot;">​</a></h3><figure><img src="'+i+'" alt="네트워크 구성도, 산업용 구성, 라우터가 스위치 허브에 통합"><figcaption style="text-align:center;">[ 산업용 · 라우터 통합 ]</figcaption></figure><h3 id="외장-라우터를-사용하는-구성-1" tabindex="-1">외장 라우터를 사용하는 구성 <a class="header-anchor" href="#외장-라우터를-사용하는-구성-1" aria-label="Permalink to &quot;외장 라우터를 사용하는 구성&quot;">​</a></h3><figure><img src="'+e+`" alt="네트워크 구성도, 산업용 구성, 외장 라우터 사용"><figcaption style="text-align:center;">[ 산업용 · 외장 라우터 ]</figcaption></figure><p>이 구성에서는 LiDAR 2가 스위치 허브에 직접 연결되지 않고 라우터를 경유합니다.</p><h2 id="네트워크-상세" tabindex="-1">네트워크 상세 <a class="header-anchor" href="#네트워크-상세" aria-label="Permalink to &quot;네트워크 상세&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>Wi-Fi</td><td>2.4 GHz, 5 GHz</td></tr><tr><td>네트워크 스위치 속도</td><td>기가비트 이더넷 (1 Gbps)</td></tr><tr><td>Access Point</td><td><code>192.168.0.1</code></td></tr></tbody></table><h2 id="pc-구성-및-ip" tabindex="-1">PC 구성 및 IP <a class="header-anchor" href="#pc-구성-및-ip" aria-label="Permalink to &quot;PC 구성 및 IP&quot;">​</a></h2><p>Motion PC(R-PC)는 모든 로봇에 기본 탑재됩니다. User PC(U-PC)는 옵션이며, 로봇 구성에 따라 탑재되지 않을 수 있습니다. <strong>U-PC의 주소는 탑재 위치에 따라 다릅니다.</strong></p><table tabindex="0"><thead><tr><th>PC</th><th>IP</th><th>역할</th><th>구성</th><th>사용자 접근</th></tr></thead><tbody><tr><td>Motion PC (R-PC)</td><td><code>192.168.0.10</code></td><td>로봇 제어</td><td>기본</td><td>불가</td></tr><tr><td>User PC (U-PC) — 로봇 내부 탑재</td><td><code>192.168.0.12</code></td><td>사용자 개발 작업</td><td>옵션</td><td>가능</td></tr><tr><td>User PC (U-PC) — 로봇 외부</td><td><code>192.168.0.13</code></td><td>사용자 개발 작업</td><td>옵션</td><td>가능</td></tr></tbody></table><p>Motion PC는 로봇 동작에 직접 관여하므로 사용자가 접근할 수 없습니다. 사용자 개발 작업은 U-PC에서 수행합니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">U-PC에 연결되지 않는 경우</p><p>U-PC의 주소는 로봇 내부에 탑재된 경우 <code>192.168.0.12</code>, 로봇 외부에 있는 경우 <code>192.168.0.13</code>입니다. 연결되지 않을 경우 U-PC에 모니터를 연결하여 현재 IP를 확인해 주세요. 다른 주소를 사용 중이라면 위 주소로 고정하여 사용해 주시기 바랍니다.</p></div></div><h3 id="time-sync" tabindex="-1">시각 동기화 <a class="header-anchor" href="#time-sync" aria-label="Permalink to &quot;시각 동기화 {#time-sync}&quot;">​</a></h3><p>R-PC가 로봇의 시각 서버입니다. 로봇이 켜져 있는 동안, 인터넷에 연결되어 있든 아니든 <code>192.168.0.10</code>, UDP 123번 포트로 <code>192.168.0.0/24</code> 대역의 모든 장비에 NTP를 제공합니다. U-PC와 같은 시각이 필요한 페이로드 PC는 인터넷 시각 서버가 아니라 R-PC를 바라보도록 설정해 주세요.</p><p>U-PC에서 다음을 실행합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/timesyncd.conf.d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/timesyncd.conf.d/zz-rbq.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[Time]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NTP=</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NTP=192.168.0.10</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FallbackNTP=</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PollIntervalMinSec=16</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PollIntervalMaxSec=64</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-ntp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-timesyncd</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-local-rtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p>설정 후 <code>timedatectl timesync-status</code>로 확인합니다. <code>Server</code>가 <code>192.168.0.10</code>이고 <code>Offset</code>이 수 ms 이내로 유지되면 정상입니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">첫 동기화에서 시각이 한 번에 바뀔 수 있습니다</p><p>U-PC 시각이 R-PC와 크게 다르면 첫 동기화에서 한 번에 맞춰지고, 이후에는 조금씩 보정됩니다. 시각에 민감한 프로그램은 <code>timedatectl</code>에 <code>System clock synchronized: yes</code>가 표시된 뒤에 실행해 주세요.</p></div></div><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">로봇 시각은 실제 시각과 다를 수 있습니다</p><p>R-PC를 따르는 장비는 모두 같은 시각을 쓰지만, 이 시각이 실제 시각과 일치한다고 보장하지는 않습니다. 로봇 장비 사이에서 데이터의 시각을 맞추는 용도로 사용하고, 실제 시각의 기준으로 쓰지 마세요.</p></div></div>`,32)])])}const u=n(o,[["render",h]]);export{P as __pageData,u as default};
